window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-458928580e61fb0a"]={"versions": [{"id": "FIG-458928580e61fb0a", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Metamodellierung im Kontext der AUTOSAR Generic Structure Template (TPS Generic Structure Template). Das Diagramm veranschaulicht unzulässige Lebenszyklus-Zustandskombinationen (LifeCycleStates) zwischen Modellelementen, ihren Beziehungsarten (Aggregation und Referenz) und den jeweiligen Zielklassen gemäß Gültigkeitsregeln der Lebenszyklus-Spezifikation.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellt sind zwei konzeptionelle Konstellationen mit jeweils zwei Klassen und deren verbindenden Relationen:</p>\n<ul class=\"fig-list\">\n<li>Linke Seite (Aggregation): Übergeordnete Klasse <code>parent: ClassA</code> aggregiert (gefüllte Raute) das untergeordnete Element <code>child: ClassB</code>.</li>\n<li>Rechte Seite (Referenz): Ausgangsklasse <code>source: ClassA</code> referenziert (gerichtete Pfeilverbindung) die Zielklasse <code>target: ClassB</code>.</li>\n<li>Tags/Stereotypen:</li>\n<li><code>parent: ClassA</code> trägt das Tag <code>atp.Status = obsolete</code>.</li>\n<li>Die Kompositionsbeziehung trägt über eine Notiz <code>aggregation Tags: atp.Status = valid</code>.</li>\n<li><code>child: ClassB</code> trägt das Tag <code>atp:Status = obsolete</code>.</li>\n<li><code>source: ClassA</code> trägt das Tag <code>atp.Status = obsolete</code>.</li>\n<li>Die Referenzbeziehung trägt über eine Notiz <code>reference Tags: atp.Status = valid</code>.</li>\n<li><code>target: ClassB</code> trägt das Tag <code>atp.Status = obsolete</code>.</li>\n<li>Zwei gestrichelte Geltungsbereiche (Scopes) rahmen die Elemente ein:</li>\n<li>Dunkelblaue Umrandung: „Scope of table status value combinations (Aggregation/Reference/Attribute/Enumeration Literal)“ umfasst <code>ClassA</code> sowie die Beziehungsnotizen.</li>\n<li>Hellblaue Umrandung: „Scope of table status value combinations with child/target Class“ umfasst zusätzlich die Zielklassen <code>ClassB</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell-Strukturdiagramm; kein dynamischer Sequenz- oder Laufzeitablauf vorhanden. Die Darstellung spezifiziert statische Konsistenzregeln für Werkzeuge und Modellvalidatoren zur Entwurfszeit.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normatives Verbot inkonsistenter <code>atp.Status</code>-Zuweisungen im M1/M2-Modell: Ein übergeordnetes bzw. quellseitiges Element mit dem Lebenszyklusstatus <code>obsolete</code> darf nicht über eine Relation (Aggregation oder Referenz) verfügen, die als <code>valid</code> deklariert ist, wenn das Zielelement den Status <code>obsolete</code> besitzt. Modellierungswerkzeuge und Validierungsregeln müssen solche ungültigen Kombinationen von LifeCycleStates als Regelverletzung zurückweisen.</p>"}, {"id": "FIG-7ae44541bacb2574", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Metamodellierung im Kontext der AUTOSAR Generic Structure Template (TPS Generic Structure Template). Das Diagramm veranschaulicht unzulässige Lebenszyklus-Zustandskombinationen (LifeCycleStates) zwischen Modellelementen, ihren Beziehungsarten (Aggregation und Referenz) und den jeweiligen Zielklassen gemäß Gültigkeitsregeln der Lebenszyklus-Spezifikation.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellt sind zwei konzeptionelle Konstellationen mit jeweils zwei Klassen und deren verbindenden Relationen:</p>\n<ul class=\"fig-list\">\n<li>Linke Seite (Aggregation): Übergeordnete Klasse <code>parent: ClassA</code> aggregiert (gefüllte Raute) das untergeordnete Element <code>child: ClassB</code>.</li>\n<li>Rechte Seite (Referenz): Ausgangsklasse <code>source: ClassA</code> referenziert (gerichtete Pfeilverbindung) die Zielklasse <code>target: ClassB</code>.</li>\n<li>Tags/Stereotypen:</li>\n<li><code>parent: ClassA</code> trägt das Tag <code>atp.Status = obsolete</code>.</li>\n<li>Die Kompositionsbeziehung trägt über eine Notiz <code>aggregation Tags: atp.Status = valid</code>.</li>\n<li><code>child: ClassB</code> trägt das Tag <code>atp:Status = obsolete</code>.</li>\n<li><code>source: ClassA</code> trägt das Tag <code>atp.Status = obsolete</code>.</li>\n<li>Die Referenzbeziehung trägt über eine Notiz <code>reference Tags: atp.Status = valid</code>.</li>\n<li><code>target: ClassB</code> trägt das Tag <code>atp.Status = obsolete</code>.</li>\n<li>Zwei gestrichelte Geltungsbereiche (Scopes) rahmen die Elemente ein:</li>\n<li>Dunkelblaue Umrandung: „Scope of table status value combinations (Aggregation/Reference/Attribute/Enumeration Literal)“ umfasst <code>ClassA</code> sowie die Beziehungsnotizen.</li>\n<li>Hellblaue Umrandung: „Scope of table status value combinations with child/target Class“ umfasst zusätzlich die Zielklassen <code>ClassB</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell-Strukturdiagramm; kein dynamischer Sequenz- oder Laufzeitablauf vorhanden. Die Darstellung spezifiziert statische Konsistenzregeln für Werkzeuge und Modellvalidatoren zur Entwurfszeit.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normatives Verbot inkonsistenter <code>atp.Status</code>-Zuweisungen im M1/M2-Modell: Ein übergeordnetes bzw. quellseitiges Element mit dem Lebenszyklusstatus <code>obsolete</code> darf nicht über eine Relation (Aggregation oder Referenz) verfügen, die als <code>valid</code> deklariert ist, wenn das Zielelement den Status <code>obsolete</code> besitzt. Modellierungswerkzeuge und Validierungsregeln müssen solche ungültigen Kombinationen von LifeCycleStates als Regelverletzung zurückweisen.</p>"}, {"id": "FIG-7e8d3818f83b2f94", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Metamodellierung im Kontext der AUTOSAR Generic Structure Template (TPS Generic Structure Template). Das Diagramm veranschaulicht unzulässige Lebenszyklus-Zustandskombinationen (LifeCycleStates) zwischen Modellelementen, ihren Beziehungsarten (Aggregation und Referenz) und den jeweiligen Zielklassen gemäß Gültigkeitsregeln der Lebenszyklus-Spezifikation.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellt sind zwei konzeptionelle Konstellationen mit jeweils zwei Klassen und deren verbindenden Relationen:</p>\n<ul class=\"fig-list\">\n<li>Linke Seite (Aggregation): Übergeordnete Klasse <code>parent: ClassA</code> aggregiert (gefüllte Raute) das untergeordnete Element <code>child: ClassB</code>.</li>\n<li>Rechte Seite (Referenz): Ausgangsklasse <code>source: ClassA</code> referenziert (gerichtete Pfeilverbindung) die Zielklasse <code>target: ClassB</code>.</li>\n<li>Tags/Stereotypen:</li>\n<li><code>parent: ClassA</code> trägt das Tag <code>atp.Status = obsolete</code>.</li>\n<li>Die Kompositionsbeziehung trägt über eine Notiz <code>aggregation Tags: atp.Status = valid</code>.</li>\n<li><code>child: ClassB</code> trägt das Tag <code>atp:Status = obsolete</code>.</li>\n<li><code>source: ClassA</code> trägt das Tag <code>atp.Status = obsolete</code>.</li>\n<li>Die Referenzbeziehung trägt über eine Notiz <code>reference Tags: atp.Status = valid</code>.</li>\n<li><code>target: ClassB</code> trägt das Tag <code>atp.Status = obsolete</code>.</li>\n<li>Zwei gestrichelte Geltungsbereiche (Scopes) rahmen die Elemente ein:</li>\n<li>Dunkelblaue Umrandung: „Scope of table status value combinations (Aggregation/Reference/Attribute/Enumeration Literal)“ umfasst <code>ClassA</code> sowie die Beziehungsnotizen.</li>\n<li>Hellblaue Umrandung: „Scope of table status value combinations with child/target Class“ umfasst zusätzlich die Zielklassen <code>ClassB</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell-Strukturdiagramm; kein dynamischer Sequenz- oder Laufzeitablauf vorhanden. Die Darstellung spezifiziert statische Konsistenzregeln für Werkzeuge und Modellvalidatoren zur Entwurfszeit.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normatives Verbot inkonsistenter <code>atp.Status</code>-Zuweisungen im M1/M2-Modell: Ein übergeordnetes bzw. quellseitiges Element mit dem Lebenszyklusstatus <code>obsolete</code> darf nicht über eine Relation (Aggregation oder Referenz) verfügen, die als <code>valid</code> deklariert ist, wenn das Zielelement den Status <code>obsolete</code> besitzt. Modellierungswerkzeuge und Validierungsregeln müssen solche ungültigen Kombinationen von LifeCycleStates als Regelverletzung zurückweisen.</p>"}], "trans": [{"from": "FIG-458928580e61fb0a", "to": "FIG-7ae44541bacb2574", "fr": "R23-11", "tr": "R24-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-7ae44541bacb2574", "to": "FIG-7e8d3818f83b2f94", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
